%分类函数
function y=fenlei(a,m)
% a是一个行向量（从小到大排序或者从大到小排序）,
% m=6是预先估计的分类个数，然后根据输出图形的结果再调整
% y=行向量，每个样品的类别
%%
[x,y,z]=sunshi(a); % z是分点矩阵n*n(例如26*26)
n=size(z,1);
a=zeros(1,n);
y=z(n,m);
a(1,y:n)=m;
t=y-1;
for j=1:(m-1)
i=m-j;
if i>1
y=z(t,i);
a(1,y:t)=i;
t=y-1;
else
a(1,1:t)=1;
end
end
y=a;
% 最优分割法--计算直径的函数
function y=zhijing(a)
% a是一个行向量（本文中是相对误差）
%%
b=size(a);
e=zeros(b(2));
for i=1:(b(2)-1)
for j=(i+1):b(2)
c=a(1,i:j);
f=size(c);
d=mean(c);
for k=1:f(2)
e(i,j)=e(i,j)+(c(1,k)-d)^2;
end
end
end
y=e;
function [x,y,z]=sunshi(a)
% a是一个行向量（从小到大排序）
% x=直径D(i,j)矩阵,是b阶方阵
% y=损失函数值L[b*(l,k)]矩阵，是b阶方阵
% z=分类位置点j 矩阵，是b阶方阵

43
%%
d=zhijing(a);% d是直径矩阵，zhijing()是自编的求直径的函数
b=length(a);
c=zeros(b);
e=zeros(b);
f=zeros(1,b);
k=2;
for i=(k+1):b
for j=k:i
f(1,j)=d(1,j-1)+d(j,i) ;
end
g=nonzeros(f);
c(i,k)=min(g);
for j=1:b
if
f(1,j)==min(g)
e(i,k)= j;
end
end
end
h=zeros(1,b);
for k=3:b-1
for i=(k+1):b
for j=k:i
h(1,j)=c(j-1,k-1)+d(j,i) ;
end
g=nonzeros(h);
c(i,k)= min(g);
for j=1:b
if
h(1,j)==min(g)
e(i,k)= j;
end
end
